package com.example.starter.maintenance.domain;

import java.time.Instant;

/**
 * 保养模板版本（设备内版本化，每个版本不可变）。
 *
 * @param equipmentId               所属设备标识
 * @param templateVersion           模板版本号，从 1 开始递增
 * @param overdueThresholdMinutes   OVERDUE 阈值（分钟）：本轮运行分钟满足 [周期, 阈值) 为 DUE，达到阈值为 OVERDUE
 * @param createdAt                 模板版本创建时刻（UTC）
 */
public record MaintenanceTemplate(
        String equipmentId,
        int templateVersion,
        long overdueThresholdMinutes,
        Instant createdAt) {
}

package com.example.starter.maintenance.domain;

import java.time.Instant;

/**
 * 材料批次台账行。撤销不可逆，台账行保留不删。
 *
 * @param batchCode      材料批次编码，全局唯一，格式 MAT- 开头加 4-16 位大写字母数字
 * @param active         是否在用：true=ACTIVE，false=REVOKED（已撤销）
 * @param description    材料描述（null 表示登记时未提供）
 * @param revokeReason   撤销原因（null 表示未撤销或未填写原因）
 * @param createdAt      登记时刻（UTC）
 * @param revokedAt      撤销时刻（UTC，未撤销时为 null）
 */
public record Material(
        String batchCode,
        boolean active,
        String description,
        String revokeReason,
        Instant createdAt,
        Instant revokedAt) {

    public static final String ACTIVE = "ACTIVE";
    public static final String REVOKED = "REVOKED";
}

package com.example.starter.maintenance.domain;

import java.time.Instant;

/**
 * 证据包头（设备某保养周期内的一个不可变版本）。
 *
 * @param equipmentId      所属设备标识
 * @param cycleNo          保养周期序号，从 1 开始；完成保养后进入下一周期
 * @param packageVersion   周期内证据包版本号，从 1 开始递增
 * @param templateVersion  该周期固化的模板版本（周期内首个证据包版本确定）
 * @param submittedBy      该版本提交人（维护人员标识），不可兼任完工确认人
 * @param createdAt        证据包版本生成时刻（UTC）
 */
public record EvidencePackage(
        String equipmentId,
        int cycleNo,
        int packageVersion,
        int templateVersion,
        String submittedBy,
        Instant createdAt) {
}

package com.example.starter.maintenance.domain;

import java.time.Instant;

/**
 * 完工后更正附录（只追加，不改变周期与工时历史）。
 *
 * @param id           自增主键
 * @param equipmentId  所属设备标识
 * @param cycleNo      关联的已完成保养周期序号
 * @param operatorId   创建附录的操作人员
 * @param note         更正说明
 * @param createdAt    附录创建时刻（UTC）
 */
public record EvidenceAppendix(
        long id,
        String equipmentId,
        int cycleNo,
        String operatorId,
        String note,
        Instant createdAt) {
}

