 * @param materials       本次追加的材料批次摘要（可空或为空列表表示仅更新检查项）
 */
public record SubmitEvidenceRequest(
        @NotBlank String requestId,
        @NotNull Long expectedVersion,
        @NotBlank String submittedBy,
