     * @param result   检查结果，仅接受 PASS 或 FAIL
     * @param remark   备注（可空，null 表示无备注）
     */
    public record CheckResultInput(
            @NotBlank String itemCode,
            @NotBlank String result,
            @Size(max = 256) String remark) {
    }

    /**
